parameters.jsCode:
// Token-overlap (Jaccard) dedupe between the new AI prompts and recently parked items.
// LLM output is never byte-identical, so exact comparison would never fire — instead we
// normalise both sides to word sets and measure overlap. Same constants as our other
// parking-lot templates — tune once, copy everywhere.
//
// THRESHOLD: 0.6 catches rewordings of the same issue. Raise it towards 0.8 if distinct
// items get swallowed as duplicates; lower it if near-duplicates slip through.
const THRESHOLD = 0.6;

const STOPWORDS = new Set([
  'the', 'a', 'an', 'and', 'or', 'but', 'for', 'with', 'when', 'that', 'this',
  'are', 'is', 'was', 'were', 'our', 'has', 'have', 'had', 'not', 'can',
  'into', 'from', 'over', 'on', 'in', 'to', 'of', 'it', 'its',
]);

function tokens(text) {
  return new Set(
    String(text)
      .toLowerCase()
      .replace(/\([^)]*\)\s*$/, ' ') // strip the "(deal name)" ref we append to parked titles
      .replace(/[^\p{L}\p{N}\s]/gu, ' ') // strip emoji and punctuation
      .split(/\s+/)
      .filter((w) => w.length > 1 && !STOPWORDS.has(w)),
  );
}

function jaccard(a, b) {
  if (a.size === 0 || b.size === 0) return 0;
  let overlap = 0;
  for (const t of a) if (b.has(t)) overlap += 1;
  return overlap / (a.size + b.size - overlap);
}

const ai = $('Draft Retro Prompts').first().json.output;
const prompts = (ai.prompts ?? []).slice(0, 2);

const existing = [];
for (const { json: item } of $input.all()) {
  const title = item.title ?? item.name ?? '';
  if (!title) continue; // alwaysOutputData emits one empty item when the lot is empty
  existing.push({ title, tok: tokens(title) });
}

const out = [];
for (const prompt of prompts) {
  const fresh = tokens(prompt);
  let bestTitle = null;
  let bestScore = 0;
  for (const e of existing) {
    const score = jaccard(fresh, e.tok);
    if (score > bestScore) {
      bestScore = score;
      bestTitle = e.title;
    }
  }
  out.push({
    json: {
      prompt,
      duplicate: bestScore >= THRESHOLD,
      matchedTitle: bestTitle,
      matchScore: Math.round(bestScore * 100) / 100,
    },
  });
  // A second near-identical prompt from the same run counts as a duplicate too.
  existing.push({ title: prompt, tok: fresh });
}

return out;
